def F(label, ph, hint=None, group=None, options=None):
    d = {"label":label, "ph":ph}
    if hint is not None: d["hint"] = hint
    if group is not None: d["group"] = group
    if options is not None: d["options"] = options
    return d

def D(label, to, title, body, askLabel, asks, attach, sub=None, closing=None):
    d = {"label":label, "to":to, "title":title, "body":body, "askLabel":askLabel, "asks":asks, "attach":attach}
    if sub: d["sub"] = sub
    if closing: d["closing"] = closing
    return d

def S(title, card, short, lead, deadline, trigger, steps, evidence, fields, docs):
    return {"title":title, "card":card, "short":short, "lead":lead, "deadline":deadline, "trigger":trigger,
            "steps":[{"org":o, "t":t, "when":w, "body":b} for o, t, w, b in steps], "evidence":evidence, "fields":fields, "docs":docs}

