def build_ru(S_uz):
    """Ruscha bazani qurib, o‘zbekcha bazaga mosligini tekshiradi."""
    import re
    out = {"laws": LAWS, "domains": {k: {"title":v[0], "desc":v[1]} for k, v in DOMAINS.items()},
           "norms": {k: {"title":v[0], "text":v[1]} for k, v in NORMS.items()},
           "applicant": [{"label":a, "ph":b, "hint":c} for a, b, c in APPLICANT],
           "extra": {"label":EXTRA[0], "ph":EXTRA[1]}, "scenarios": {}}
    for s in S_uz:
        r = SC[s["id"]]
        assert len(r["steps"]) == len(s["steps"]), ("steps", s["id"])
        assert len(r["evidence"]) == len(s["evidence"]), ("evidence", s["id"])
        assert len(r["fields"]) == len(s["fields"]), ("fields", s["id"])
        assert len(r["docs"]) == len(s["docs"]), ("docs", s["id"])
        assert set(r["deadline"]) == set(s["deadline"]) & {"label", "note"}, ("deadline", s["id"])
        for fu, fr in zip(s["fields"], r["fields"]):
            assert set(fr) == set(fu) & {"label","ph","hint","group","options"}, ("field", s["id"], fu["k"], set(fu) ^ set(fr))
            if fu.get("options"): assert len(fr["options"]) == len(fu["options"]), ("options", s["id"])
        keys_uz = set(re.findall(r"\{\{(\w+)\}\}|\[[?!](\w+)\]", str(s["docs"])))
        for du, dr in zip(s["docs"], r["docs"]):
            ku = {a or b for a, b in re.findall(r"\{\{(\w+)\}\}|\[[?!](\w+)\]", str(du))}
            kr = {a or b for a, b in re.findall(r"\{\{(\w+)\}\}|\[[?!](\w+)\]", str(dr))}
            assert set(dr) == set(du) - {"id", "howto"}, (s["id"], du["id"], set(du) ^ set(dr))
            assert kr <= ku | {"applicant", "trigger", "deadline", "deadlineTerm"}, (s["id"], du["id"], kr - ku)
            # yo‘riqnoma: o‘zbekcha bilan bir xil tur va bog‘lamalar
            kind = "fine" if s["id"] == "jarima" else "private" if du["id"] in ("employer","seller","debtor") else "court" if du["id"] == "court" else "state"
            steps = list(HOW[kind])
            if kind == "court":
                fee = FEE["admin"] if s["domain"] == "davlat" else FEE["mehnat"] if s["domain"] == "mehnat" else FEE["aliment"] if s["id"] == "aliment" else FEE["qarz"] if s["id"] == "qarz" else None
                if fee: steps.append(fee)
            dr["howto"] = {"steps": steps, "links": [{"label": LINK_LABELS[l["url"]]} for l in du["howto"]["links"]]}
        out["scenarios"][s["id"]] = r
    return out
